.timeline {
position:absolute;
left:50%;
width:2px;
height:100%;
margin-left:-1px
}

.timeline__content-title {
font-weight:400;
font-size:66px;
margin:-10px 0 0;
padding:0 10px;
font-family:'Pathway Gothic One', sans-serif;
color:#fff
}

.timeline__content-desc {
margin:0;
font-size:1.2em;
font-family:Cardo;
font-weight:400;
line-height:25px
}

@media only screen and (max-width: 767px) {
.timeline {
left:40px
}
}

.timeline-item {
right:auto;
text-align:right;
padding-left:0;
border-left:none;
border-right:2px solid;
padding-right:15px
}

div.prizes {
display:none;
font-size:1.3em;
font-family:'Pathway Gothic One', sans-serif;
position:absolute;
top:60%;
width:100%;
margin-top:-5px;
padding-left:15px
}

.timeline-item--active div.prizes {
text-align:right;
padding-right:2em
}

.timeline-item--active div.prizes.fields {
left:auto;
right:-.6em
}

.timeline-item--active {
top:50%;
opacity:1
}

.timeline-item--active .timeline__content-title {
margin:-50px 0 20px
}

@media only screen and (max-width: 767px) {
div.prizes {
display:none;
font-size:1em;
font-family:'Pathway Gothic One', sans-serif;
position:absolute;
padding-left:2em;
text-align:left;
top:-1.2em;
width:80%
}

.timeline-item--active div.prizes {
display:block;
left:10px
}

.timeline-item--active div.prizes.fields {
width:1em;
height:1em;
top:.2em;
left:.8em
}

.timeline-item {
padding-bottom:40px
}
}

.timeline__img {
}

.timeline-container {
position:absolute;
left:0;
top:0;
width:100%;
height:100%
}

.timeline-header {
width:100%;
text-align:center;
margin-bottom:80px;
padding-bottom:20px;
position:relative
}

.timeline-header__title {
color:#fff;
font-size:46px;
font-family:Cardo;
font-weight:400;
margin:0
}

.timeline-header__subtitle {
font-family:'Pathway Gothic One', sans-serif;
font-size:1.2em;
letter-spacing:2px;
margin:10px 0 0;
font-weight:400
}

.demo-footer {
padding:60px 0;
text-align:center
}

.demo-footer a {
color:#999;
display:inline-block;
font-family:Cardo
}
-->
